describe('isValidEmail', () => {
  it('should return true for valid email addresses', () => {
    expect(isValidEmail('user@example.com')).toBe(true);
    expect(isValidEmail('test.user+tag@domain.co.uk')).toBe(true);
  });

  it('should return false for invalid email addresses', () => {
    expect(isValidEmail('invalid')).toBe(false);
    expect(isValidEmail('missing@domain')).toBe(false);
    expect(isValidEmail('@nodomain.com')).toBe(false);
    expect(isValidEmail('spaces in@email.com')).toBe(false);
  });

  it('should return false for empty string', () => {
    expect(isValidEmail('')).toBe(false);
  });
});

describe('sanitizeInput', () => {
  it('should escape HTML special characters', () => {
    expect(sanitizeInput('<script>alert("xss")</script>')).toBe('&lt;script&gt;alert(&quot;xss&quot;)&lt;/script&gt;');
    expect(sanitizeInput('<img src="x" onerror="alert(1)">')).toBe('&lt;img src=&quot;x&quot; onerror=&quot;alert(1)&quot;&gt;');
  });

  it('should escape single quotes', () => {
    expect(sanitizeInput("It's a test")).toBe('It&#039;s a test');
  });

  it('should handle normal text without modification', () => {
    expect(sanitizeInput('Hello World')).toBe('Hello World');
    expect(sanitizeInput('User Name 123')).toBe('User Name 123');
  });

  it('should handle empty string', () => {
    expect(sanitizeInput('')).toBe('');
  });
});

describe('createUser', () => {
  it('should create a user with valid input', async () => {
    const input = { email: 'Test@Example.COM', name: 'John Doe' };
    const user = await createUser(input);

    expect(user.id).toMatch(/^user_\d+_[a-z0-9]+$/);
    expect(user.email).toBe('test@example.com');
    expect(user.name).toBe('John Doe');
    expect(user.createdAt).toBeInstanceOf(Date);
  });

  it('should sanitize user name', async () => {
    const input = { email: 'user@test.com', name: '<script>Bad</script>' };
    const user = await createUser(input);

    expect(user.name).toBe('&lt;script&gt;Bad&lt;/script&gt;');
  });

  it('should throw error when email is missing', async () => {
    await expect(createUser({ email: '', name: 'John' }))
      .rejects.toThrow('Email and name are required');
  });

  it('should throw error when name is missing', async () => {
    await expect(createUser({ email: 'test@example.com', name: '' }))
      .rejects.toThrow('Email and name are required');
  });

  it('should throw error for invalid email format', async () => {
    await expect(createUser({ email: 'invalid-email', name: 'John' }))
      .rejects.toThrow('Invalid email format');
  });
});

it('should throw error when both email and name are missing', async () => {
  await expect(createUser({ email: '', name: '' }))
